// TypeScript: interface Props { name: string; role?: string }
// A "component" is a function of its props (here, returning a string).
function renderCard(props) {
  const role = props.role || "member";
  return "<div><h2>" + props.name + "</h2><p>" + role + "</p></div>";
}
console.log(renderCard({ name: "Roli" }));

