// TypeScript: useState<string>("a") — state holds a string.
// Model it: [get, set] where set rejects non-strings.
function makeState(initial) {
  let value = initial;
  const get = () => value;
  const set = (v) => {
    if (typeof v !== "string") throw new TypeError("string state only");
    value = v;
  };
  return [get, set];
}
const [get, set] = makeState("a");
set("b");
console.log(get());

